<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;class ProductVersion extends Model{protected $fillable=['product_id','version_number','status','snapshot','change_summary','submitted_by','submitted_at','reviewed_at'];protected $casts=['snapshot'=>'array','submitted_at'=>'datetime','reviewed_at'=>'datetime'];public function product(){return $this->belongsTo(Product::class);}public function submitter(){return $this->belongsTo(User::class,'submitted_by');}}